{
  "book_code": "TADAM",
  "verses": [
    {
      "chapter": 12,
      "verse": 2,
      "text_ar": "في وسط الملائكة، ومن أجلك طُرِحتُ أنا في الأرض'. فأجاب آدم: 'ماذا"
    },
    {
      "chapter": 12,
      "verse": 3,
      "text_ar": "تخبرني؟ ماذا صنعتُ إليك، أو ما هو ذنبي ضدك، وبما أنك لم تتلقَّ أضراراً أو إصابات منا، فلماذا تلاحقنا؟'"
    },
    {
      "chapter": 13,
      "verse": 1,
      "text_ar": "فأجاب إبليس: 'يا آدم، ماذا تخبرني؟ من أجلك أنتَ جرى طرحي"
    },
    {
      "chapter": 13,
      "verse": 2,
      "text_ar": "من ذلك المكان. فعندما صُوِّرتَ، طُرِحتُ أنا من حضرة الله ونُفِيتُ من شركة الملائكة. وعندما نفخ الله فيك نسمة الحياة وصُنِع وجهك وشبهك على صورة الله، أتاك ميخائيل أيضاً وجعلنا نسجد لك أمام الله؛ وتكلم الله الرب قائلاً: هوذا آدم. لقد صنعْتُك على صورتنا وشبهنا'."
    },
    {
      "chapter": 14,
      "verse": 1,
      "text_ar": "وخرج ميخائيل ودعا جميع الملائكة قائلاً: 'اسجدوا لصورة الله كما أمر الرب الإله'. وسجد ميخائيل بنفسه أولاً؛ ثم دعاني وقال: 'اسجد لصورة الله'"
    }
  ]
}
